import { offBrands, offNutritionPer100g, offProductName, type OffNutritionPer100g } from '@motivation/shared';
import { API_URL } from '../config.js';
import { apiError } from './http.js';

const OFF_PROXY_BASE = `${API_URL}/api/sections/health/openfoodfacts`;

/** Story 369: the nutrients are the shared reading — absent means OFF did not report it. */
export interface OFFProduct extends OffNutritionPer100g {
    product_name: string;
    brands?: string;
    image_url?: string;
    barcode?: string;
    serving_size?: string;
    serving_quantity?: number;
    quantity?: string;
    product_quantity?: number;
    categories_tags?: string[];
    countries_tags?: string[];
    /**
     * Story 337 — set when the server could not find this exact barcode and resolved
     * it through the in-store item code instead (spike 336). The nutrition below then
     * belongs to a DIFFERENT package of the same product, so the UI must say so.
     */
    matched_by?: 'item_code';
    /** The sibling barcode the product actually came from, when `matched_by` is set. */
    matched_barcode?: string;
}

/**
 * Story 339 — why a barcode lookup produced no product. `lookupBarcode` used to
 * collapse all four into `null`, which is why the September dead ends could not be
 * told apart without pairing request-log lines by timestamp.
 */
export type OffLookupOutcome =
    /** OFF had this exact barcode. */
    | 'found'
    /** Story 337: the exact code missed, an item-code sibling answered. */
    | 'found_by_item_code'
    /** OFF answered, and genuinely does not have it. Permanent, not a blip. */
    | 'not_found'
    /** OFF (or the proxy) failed — a 5xx. Worth retrying; not the product's fault. */
    | 'upstream_error'
    /** The request never got an answer: offline, DNS, abort. */
    | 'network_error';

export interface OFFLookupResult {
    product: OFFProduct | null;
    outcome: OffLookupOutcome;
    /** HTTP status the proxy returned, when there was one. */
    status?: number;
}

export interface OFFSearchPage {
    items: OFFProduct[];
    page: number;
    pageCount: number;
    totalCount: number;
}

/** OFF sends these as numbers or numeric strings, depending on the product. */
function positiveNumber(value: unknown): number | undefined {
    const n = typeof value === 'string' ? parseFloat(value) : value;
    return typeof n === 'number' && Number.isFinite(n) && n > 0 ? n : undefined;
}

/** The fields both the barcode lookup and the search read off a product. */
function toProduct(p: any): Omit<OFFProduct, 'barcode'> {
    return {
        product_name: offProductName(p) ?? 'Unknown Product',
        brands: offBrands(p.brands),
        image_url: p.image_front_url || undefined,
        serving_size: p.serving_size || undefined,
        serving_quantity: positiveNumber(p.serving_quantity),
        quantity: p.quantity || undefined,
        product_quantity: positiveNumber(p.product_quantity),
        categories_tags: Array.isArray(p.categories_tags) ? p.categories_tags : undefined,
        ...offNutritionPer100g(p.nutriments),
    };
}

export class OpenFoodFactsService {
    /**
     * Story 339 — reports WHY, not just whether. A 404 is the product genuinely not
     * existing; a 5xx is OFF having a bad day; a throw is the phone. They need three
     * different reactions and used to be one `null`.
     */
    static async lookupBarcode(barcode: string): Promise<OFFLookupResult> {
        let response: Response;
        try {
            response = await fetch(`${OFF_PROXY_BASE}/product/${barcode}`);
        } catch {
            return { product: null, outcome: 'network_error' };
        }
        try {
            if (!response.ok) {
                return {
                    product: null,
                    outcome: response.status === 404 ? 'not_found' : 'upstream_error',
                    status: response.status,
                };
            }

            const data = await response.json();
            if (data.status !== 1 || !data.product) {
                return { product: null, outcome: 'not_found', status: response.status };
            }

            const p = data.product;
            // Story 337: on an item-code match the product is a sibling package, so the
            // barcode that identifies it is the MATCHED one, not the one scanned — that
            // is what makes the save-time dedupe find an existing row next time.
            const matchedByItemCode = data.matched_by === 'item_code' && typeof data.matched_barcode === 'string';
            const product: OFFProduct = {
                ...toProduct(p),
                barcode: matchedByItemCode ? data.matched_barcode : barcode,
                matched_by: matchedByItemCode ? 'item_code' : undefined,
                matched_barcode: matchedByItemCode ? data.matched_barcode : undefined,
            };
            return {
                product,
                outcome: matchedByItemCode ? 'found_by_item_code' : 'found',
                status: response.status,
            };
        } catch {
            // A 200 whose body will not parse is the proxy misbehaving, not a missing
            // product — grouping it with "not found" is what hid this class of failure.
            return { product: null, outcome: 'upstream_error', status: response.status };
        }
    }

    /**
     * Story 372 (pwa-nutrition-12): an abort rejects with its AbortError. It used to come back
     * as an empty page, which every caller read as "OFF has nothing".
     */
    static async searchFood(query: string, options?: { signal?: AbortSignal; page?: number }): Promise<OFFSearchPage> {
        const page = options?.page ?? 1;
        const params = new URLSearchParams({
            q: query,
            page_size: '50',
            page: page.toString(),
        });
        const response = await fetch(`${OFF_PROXY_BASE}/search?${params}`, {
            signal: options?.signal,
        });
        if (!response.ok) {
            throw await apiError(response, 'Open Food Facts search failed');
        }

        const data = await response.json();
        if (!data.products || !Array.isArray(data.products)) {
            return { items: [], page, pageCount: 0, totalCount: 0 };
        }

        const products = data.products.map((p: any): OFFProduct => ({
            ...toProduct(p),
            barcode: p.code || undefined,
            countries_tags: Array.isArray(p.countries_tags) ? p.countries_tags : undefined,
        }));

        const ranked = this.rankByRelevance(products, query);

        // Page 1: promote Dutch-country products to the top of the list so the user
        // sees familiar supermarket brands first. Subsequent pages just use the ranked
        // list as-is, so "Load More" expands with progressively more global results.
        let items: OFFProduct[];
        if (page === 1) {
            const dutch = ranked.filter(p => p.countries_tags?.includes('en:netherlands'));
            const dutchBarcodes = new Set(dutch.map(p => p.barcode));
            const rest = ranked.filter(p => !dutchBarcodes.has(p.barcode));
            items = [...dutch, ...rest];
        } else {
            items = ranked;
        }

        return {
            items,
            page,
            pageCount: typeof data.page_count === 'number' ? data.page_count : 0,
            totalCount: typeof data.count === 'number' ? data.count : items.length,
        };
    }

    /**
     * Score products by relevance to the query. Prefers:
     * - Products where query words appear in the product name (not just ingredients)
     * - Shorter product names (more likely to be the actual product, not a variant)
     * - Product names that start with the query
     */
    static rankByRelevance(products: OFFProduct[], query: string): OFFProduct[] {
        const queryLower = query.toLowerCase().trim();
        const words = queryLower.split(/\s+/).filter(w => w.length > 1);
        if (words.length === 0) return products;

        return products
            .map(p => {
                const name = p.product_name.toLowerCase();
                const brands = (p.brands ?? '').toLowerCase();
                const nameAndBrands = (name + ' ' + brands);
                const nameWords = name.split(/\s+/);

                // Base: how many query words appear in name+brands
                const matches = words.filter(w => nameAndBrands.includes(w)).length;
                if (matches === 0) return { product: p, score: 0 };

                let score = matches * 10;

                // Massive bonus for exact name match (raw ingredients often just named "Apple")
                if (name === queryLower) score += 50;

                // Bonus: query words that match as whole words in the product name
                const wholeWordMatches = words.filter(w => nameWords.some(nw => nw === w || nw.startsWith(w))).length;
                score += wholeWordMatches * 5;

                // Bonus: product name starts with the query
                if (name.startsWith(queryLower)) score += 15;

                // Bonus: short product names are more likely to be the base product
                // (e.g., "Banana" scores higher than "Banana Chocolate Milkshake Deluxe")
                if (nameWords.length <= 1) score += 20; // Single word items are very likely raw ingredients
                else if (nameWords.length <= 3) score += 8;
                else if (nameWords.length <= 5) score += 4;

                // Bonus for "clean" brands (generic products often have no brand or brand same as name)
                if (!p.brands || brands === name) score += 10;

                // Bonus for raw ingredient categories
                const isRaw = p.categories_tags?.some(t =>
                    t.includes('raw') ||
                    t.includes('fresh-') ||
                    t.includes('fruits') ||
                    t.includes('vegetables') ||
                    t.includes('eggs')
                );
                if (isRaw) score += 15;

                return { product: p, score };
            })
            .sort((a, b) => b.score - a.score)
            .filter(r => r.score > 0)
            .map(r => r.product);
    }

    /**
     * Get a sensible step increment for adjusting serving size.
     * Adapts to the current serving weight.
     */
    static getServingStep(currentGrams: number): number {
        if (currentGrams <= 50) return 5;
        if (currentGrams <= 200) return 25;
        if (currentGrams <= 500) return 50;
        return 100;
    }

    /**
     * Quick-select portion presets. Each multiplies the amount currently entered.
     */
    static getPortionPresets(): { multiplier: number }[] {
        return [{ multiplier: 0.5 }, { multiplier: 1.5 }, { multiplier: 2 }];
    }
}
