import stylesText from './food-picker.css?inline';
import bindingStylesText from '../../barcode-binding.css?inline';
import { cssStyleSheet } from '../../../../utils/css.js';
import { createComponentLogger } from '../../../../utils/component-logger.js';
import { MEAL_TYPES, inStoreItemCode, type FoodItem, type Meal, type MealType } from '@motivation/shared';
import { HealthService } from '../../../../services/health.service.js';
import type { OFFProduct } from '../../../../services/openfoodfacts.service.js';
import { FoodSearchPipeline, resolveScannedBarcode, type FoodSearchSink, type ScanResolution } from './food-search-pipeline.js';
import {
    FOOD_PICK_ACTIONS,
    HEALTH_EVENTS,
    createFoodPickActionEvent,
    createFoodPickEvent,
    type BindConsentChangeEvent,
    type FoodCardEntry,
    type FoodCardSelectEvent,
    type FoodPickAction,
} from '../../health-events.js';
import '../food-card/food-card.component.js';
import '../../barcode-scanner/barcode-scanner.component.js';
import '../../barcode-binding-banner.component.js';
import type { FoodCard } from '../food-card/food-card.component.js';
import type { BarcodeScanner } from '../../barcode-scanner/barcode-scanner.component.js';

const styles = cssStyleSheet(stylesText);
const bindingStyles = cssStyleSheet(bindingStylesText);
const log = createComponentLogger('food-picker');

const TYPE_DELAY_MS = 250;
const TILE_LIMIT = 24;

const ACTION_LABELS: Record<FoodPickAction, string> = { scan: 'Scan', label: 'Label', estimate: 'Estimate' };
// Story 433: the actions are one card of icon-over-label cells, as in the prototype.
const svg = (d: string) => `<svg viewBox="0 0 24 24" width="22" height="22" fill="none" stroke="currentColor" stroke-width="1.8" stroke-linecap="round" stroke-linejoin="round" aria-hidden="true">${d}</svg>`;
const ACTION_ICONS: Record<FoodPickAction, string> = {
    scan: svg('<path d="M4 7V5a1 1 0 0 1 1-1h2M17 4h2a1 1 0 0 1 1 1v2M20 17v2a1 1 0 0 1-1 1h-2M7 20H5a1 1 0 0 1-1-1v-2M8 8v8M11 8v8M14 8v8M17 8v8"/>'),
    label: svg('<rect x="5" y="3" width="14" height="18" rx="2"/><path d="M8 7h8M8 11h8M8 15h5"/>'),
    estimate: svg('<path d="M12 3l1.8 4.7L18.5 9.5l-4.7 1.8L12 16l-1.8-4.7L5.5 9.5l4.7-1.8z"/><path d="M18 15l.8 2.2L21 18l-2.2.8L18 21l-.8-2.2L15 18l2.2-.8z"/>'),
};

const template = document.createElement('template');
template.innerHTML = `
    <section class="scan" aria-label="Scan a barcode" hidden>
        <div class="scanner-host"></div>
        <p class="scan-status" role="status" hidden></p>
        <button type="button" class="scan-cancel">Cancel scan</button>
    </section>
    <div class="miss" hidden>
        <p class="scan-miss" role="alert"></p>
        <barcode-binding-banner id="map-barcode-banner" class="map-banner" kind="offer"></barcode-binding-banner>
    </div>
    <form class="search" role="search">
        <input type="search" class="query" placeholder="Search foods" aria-label="Search foods" autocomplete="off" enterkeyhint="search">
    </form>
    <div class="actions"></div>
    <section class="frequent" aria-label="Frequent">
        <h3 class="heading">Frequent</h3>
        <div class="tiles"></div>
        <p class="frequent-error" role="alert" hidden></p>
    </section>
    <section class="results" aria-label="Results" hidden>
        <p class="loading" hidden>Searching…</p>
        <p class="error" role="alert" hidden></p>
        <div class="list"></div>
        <p class="empty" hidden></p>
        <button type="button" class="more" hidden>More from Open Food Facts</button>
    </section>
`;

/**
 * Story 420 — the one way to find something to log or add (418): the library and saved meals
 * as you type, Open Food Facts on Enter (story 373's pipeline), frequent tiles for the slot
 * when the box is empty, and the scan / label / estimate actions. Picks are
 * `health:food-pick` (a food, a meal, or an OFF product); an action is `health:food-pick-action`.
 *
 *   <food-picker meal-type="Lunch" meals actions="scan label estimate"></food-picker>
 *
 * `meals` includes saved meals (the log flow; a meal's ingredient picker leaves it off).
 *
 * Story 432 — Scan is the picker's own, so every host has it, a sheet over an editor included:
 * the scanner opens in place, a found code is a pick (`scanned`), and a code nothing knows stays
 * here as a miss with the opt-in to teach it to the next pick (`bind`, 340/342/344), which the
 * host binds. Label and Estimate stay the host's (`health:food-pick-action`).
 */
export class FoodPicker extends HTMLElement {
    static get observedAttributes() { return ['meal-type', 'meals', 'actions']; }

    private pipeline: FoodSearchPipeline | null = null;
    private typing: ReturnType<typeof setTimeout> | null = null;
    private loadedFor: string | null = null;
    /** A scanned code nothing knew, and whether the user agreed to teach it to the next pick. */
    private deadEnd: string | null = null;
    private consent = false;
    /** Bumped by every scan and cancel, so a late lookup of a left scan is dropped. */
    private scanGeneration = 0;

    constructor() {
        super();
        const shadow = this.attachShadow({ mode: 'open' });
        shadow.adoptedStyleSheets = [styles, bindingStyles];
        shadow.appendChild(template.content.cloneNode(true));
        shadow.querySelector('.scan-cancel')!.addEventListener('click', () => this.closeScan());
        (shadow.querySelector('barcode-binding-banner') as HTMLElement).addEventListener(HEALTH_EVENTS.BIND_CONSENT_CHANGE, (e: BindConsentChangeEvent) => {
            e.stopPropagation();
            this.consent = e.detail.consent;
            // Story 344: only once the next tap means it does the screen ask "which food is this?".
            this.input.placeholder = this.consent ? 'Search for the food this barcode means…' : 'Search foods';
        });

        const form = shadow.querySelector('.search') as HTMLFormElement;
        form.addEventListener('submit', (e) => {
            e.preventDefault();
            this.clearTyping();
            const q = this.query();
            if (q.length >= 2) {
                this.showResults(true);
                this.search().search(q);
            }
        });
        this.input.addEventListener('input', () => {
            this.clearTyping();
            const q = this.query();
            if (q.length < 2) {
                this.search().reset();
                this.showResults(false);
                return;
            }
            this.typing = setTimeout(() => {
                this.showResults(true);
                void this.search().searchLocal(q);
            }, TYPE_DELAY_MS);
        });
        shadow.querySelector('.more')!.addEventListener('click', () => void this.search().loadMore());
        shadow.addEventListener(HEALTH_EVENTS.FOOD_CARD_SELECT, (e: Event) => {
            e.stopPropagation();
            // A pick leaves the results to come back to, but stops a pending OFF page.
            this.pipeline?.stopOff();
            this.dispatchEvent(createFoodPickEvent({ entry: (e as FoodCardSelectEvent).detail.entry, bind: this.pendingBind }));
        });
        shadow.querySelector('.actions')!.addEventListener('click', (e) => {
            const action = (e.target as HTMLElement).closest<HTMLButtonElement>('button')?.dataset.action as FoodPickAction | undefined;
            if (action === 'scan') this.openScan();
            else if (action) this.dispatchEvent(createFoodPickActionEvent({ action, query: this.query() }));
        });
    }

    /**
     * A code nothing knew, shown as the miss with the offer to teach it — after the picker's own
     * scan, or when a host opens on one (the add flow's `?barcode=` of an unknown code).
     */
    showMiss(barcode: string | null): void {
        const shadow = this.shadowRoot!;
        this.deadEnd = barcode;
        this.consent = false;
        this.input.placeholder = 'Search foods';
        (shadow.querySelector('.miss') as HTMLElement).hidden = !barcode;
        shadow.querySelector('.scan-miss')!.textContent = barcode ? `Product not found for barcode ${barcode}.` : '';
        const banner = shadow.querySelector('barcode-binding-banner') as HTMLElement;
        banner.removeAttribute('consent');
        if (barcode) banner.setAttribute('barcode', barcode);
        else banner.removeAttribute('barcode');
    }

    /** The dead-end code the next pick would be taught, when the user agreed to it. */
    get pendingBind(): string | null {
        return this.deadEnd && this.consent ? this.deadEnd : null;
    }

    private openScan(): void {
        const shadow = this.shadowRoot!;
        this.scanGeneration += 1;
        this.showMiss(null);
        const scanner = document.createElement('barcode-scanner') as BarcodeScanner;
        scanner.onBarcodeDetected = (barcode) => void this.lookUp(barcode);
        shadow.querySelector('.scanner-host')!.replaceChildren(scanner);
        (shadow.querySelector('.scan-status') as HTMLElement).hidden = true;
        this.toggleScan(true);
    }

    /**
     * Leaving the scanner stops the camera: the element goes, and disconnecting stops it. A host
     * that hides the picker without removing it (a closed sheet) calls this.
     */
    closeScan(): void {
        this.scanGeneration += 1;
        this.shadowRoot!.querySelector('.scanner-host')!.replaceChildren();
        this.toggleScan(false);
    }

    private toggleScan(on: boolean): void {
        const shadow = this.shadowRoot!;
        (shadow.querySelector('.scan') as HTMLElement).hidden = !on;
        for (const sel of ['.search', '.actions', '.frequent', '.results']) shadow.querySelector<HTMLElement>(sel)!.classList.toggle('scanning', on);
    }

    /** Story 373's lookup: a library food or an OFF product is the pick; nothing is the miss. */
    private async lookUp(barcode: string): Promise<void> {
        const generation = this.scanGeneration;
        const shadow = this.shadowRoot!;
        const status = shadow.querySelector('.scan-status') as HTMLElement;
        shadow.querySelector('.scanner-host')!.replaceChildren();
        status.textContent = `Looking up ${barcode}…`;
        status.hidden = false;
        let scan: ScanResolution;
        try {
            scan = await resolveScannedBarcode(barcode, log);
        } catch (err) {
            if (generation !== this.scanGeneration) return;
            this.closeScan();
            this.showError(`Could not look up ${barcode}: ${err instanceof Error ? err.message : String(err)}`);
            return;
        }
        if (generation !== this.scanGeneration) return;
        this.closeScan();
        if (scan.kind === 'library') {
            this.dispatchEvent(createFoodPickEvent({ entry: { kind: 'food', item: scan.item }, scanned: { barcode, pending: scan.pending } }));
        } else if (scan.kind === 'product') {
            this.dispatchEvent(createFoodPickEvent({ entry: { kind: 'off', product: scan.product }, scanned: { barcode, pending: scan.pending } }));
        } else {
            log.warn('barcode scan unresolved', {
                barcode, barcodeClass: inStoreItemCode(barcode) ? 'in_store' : 'gs1', library: scan.library, off: scan.off, status: scan.status,
            });
            this.showMiss(barcode);
            this.focusSearch();
        }
    }

    private showError(message: string): void {
        const error = this.shadowRoot!.querySelector('.error') as HTMLElement;
        error.textContent = message;
        error.hidden = false;
        this.showResults(true);
    }

    connectedCallback(): void {
        this.renderActions();
        void this.loadFrequent();
    }

    disconnectedCallback(): void {
        this.clearTyping();
        this.pipeline?.reset();
        this.closeScan();
    }

    attributeChangedCallback(name: string): void {
        if (name === 'actions') this.renderActions();
        if (name === 'meals') this.pipeline = null;
        if (name === 'meal-type' && this.isConnected) void this.loadFrequent();
    }

    /** Put the cursor in the search box — the log flow's first screen. */
    focusSearch(): void {
        this.input.focus();
    }

    private get input(): HTMLInputElement {
        return this.shadowRoot!.querySelector('.query') as HTMLInputElement;
    }

    private query(): string {
        return this.input.value.trim();
    }

    private clearTyping(): void {
        if (this.typing !== null) clearTimeout(this.typing);
        this.typing = null;
    }

    private showResults(on: boolean): void {
        const shadow = this.shadowRoot!;
        (shadow.querySelector('.results') as HTMLElement).hidden = !on;
        (shadow.querySelector('.frequent') as HTMLElement).hidden = on;
    }

    private search(): FoodSearchPipeline {
        const shadow = this.shadowRoot!;
        this.pipeline ??= new FoodSearchPipeline({
            results: () => this.sink(),
            loading: () => shadow.querySelector('.loading') as HTMLElement,
            error: () => shadow.querySelector('.error') as HTMLElement,
        }, log, { meals: this.hasAttribute('meals') });
        return this.pipeline;
    }

    /** The pipeline's results surface, drawn as `<food-card>` rows: meals, library, then OFF. */
    private sink(): FoodSearchSink {
        const shadow = this.shadowRoot!;
        const list = shadow.querySelector('.list') as HTMLElement;
        const more = shadow.querySelector('.more') as HTMLButtonElement;
        const empty = shadow.querySelector('.empty') as HTMLElement;
        const group = (kind: FoodCardEntry['kind']): HTMLElement => {
            let el = list.querySelector<HTMLElement>(`[data-group="${kind}"]`);
            if (!el) {
                el = document.createElement('div');
                el.dataset.group = kind;
                el.setAttribute('role', 'list');
                // Order is fixed whatever answers first.
                const order: FoodCardEntry['kind'][] = ['meal', 'food', 'off'];
                const after = [...list.children].find((c) => order.indexOf((c as HTMLElement).dataset.group as FoodCardEntry['kind']) > order.indexOf(kind));
                list.insertBefore(el, after ?? null);
            }
            return el;
        };
        const cards = (entries: FoodCardEntry[]) => entries.map((entry) => {
            const card = document.createElement('food-card') as FoodCard;
            card.setAttribute('role', 'listitem');
            card.entry = entry;
            return card;
        });
        empty.hidden = true;
        return {
            set libraryItems(items: FoodItem[]) { group('food').replaceChildren(...cards(items.map((item) => ({ kind: 'food' as const, item })))); },
            set meals(meals: Meal[]) { group('meal').replaceChildren(...cards(meals.map((meal) => ({ kind: 'meal' as const, meal })))); },
            set offItems(products: OFFProduct[]) { group('off').replaceChildren(...cards(products.map((product) => ({ kind: 'off' as const, product })))); },
            appendOffItems(products: OFFProduct[]) { group('off').append(...cards(products.map((product) => ({ kind: 'off' as const, product })))); },
            set showLoadMore(on: boolean) { more.hidden = !on; },
            clear() {
                list.replaceChildren();
                more.hidden = true;
                empty.hidden = true;
            },
            showEmpty(message: string) {
                empty.textContent = message;
                empty.hidden = false;
            },
        };
    }

    private renderActions(): void {
        const wanted = (this.getAttribute('actions') ?? '').split(/\s+/).filter((a): a is FoodPickAction => (FOOD_PICK_ACTIONS as readonly string[]).includes(a));
        const box = this.shadowRoot!.querySelector('.actions') as HTMLElement;
        box.hidden = wanted.length === 0;
        box.replaceChildren(...wanted.map((action) => {
            const button = document.createElement('button');
            button.type = 'button';
            button.className = 'action';
            button.dataset.action = action;
            button.innerHTML = `${ACTION_ICONS[action]}<span>${ACTION_LABELS[action]}</span>`;
            return button;
        }));
    }

    /** Frequent tiles for the slot (story 276), or recent foods when there is no slot. */
    private async loadFrequent(): Promise<void> {
        const shadow = this.shadowRoot!;
        const mealType = this.getAttribute('meal-type');
        const key = mealType ?? '';
        if (this.loadedFor === key) return;
        this.loadedFor = key;
        const tiles = shadow.querySelector('.tiles') as HTMLElement;
        const error = shadow.querySelector('.frequent-error') as HTMLElement;
        error.hidden = true;
        try {
            let entries: FoodCardEntry[];
            if (mealType !== null && (MEAL_TYPES as readonly string[]).includes(mealType)) {
                const frequent = await HealthService.getFrequentEntries(mealType as MealType, TILE_LIMIT);
                entries = frequent
                    .filter((f) => f.kind === 'food' || this.hasAttribute('meals'))
                    .map((f) => (f.kind === 'food' ? { kind: 'food' as const, item: f.item } : { kind: 'meal' as const, meal: f.meal }));
            } else {
                entries = (await HealthService.getRecentFoodItems(TILE_LIMIT)).map((item) => ({ kind: 'food' as const, item }));
            }
            if (this.loadedFor !== key) return;
            tiles.replaceChildren(...entries.map((entry) => {
                const card = document.createElement('food-card') as FoodCard;
                card.setAttribute('variant', 'tile');
                card.entry = entry;
                return card;
            }));
            (shadow.querySelector('.frequent') as HTMLElement).classList.toggle('none', entries.length === 0);
        } catch (err) {
            this.loadedFor = null;
            log.error('frequent tiles failed', { mealType, error: String(err) });
            error.textContent = err instanceof Error ? err.message : String(err);
            error.hidden = false;
        }
    }
}

if (!customElements.get('food-picker')) {
    customElements.define('food-picker', FoodPicker);
}
