import stylesText from './photo-controls.css?inline';
import { cssStyleSheet } from '../../../utils/css.js';
import type { ImageScope } from '@motivation/shared';
import { FilesService } from '../../../services/files.service.js';
import { cancelQueuedUpload } from '../../../services/offline/cancel-queued-upload.js';
import { IMAGE_UPLOAD_SUCCESS_CHANNEL, type ImageUploadSuccessMessage } from '../../../services/offline/image-upload-shipping.js';
import { createComponentLogger } from '../../../utils/component-logger.js';
import { dispatchAndSettle } from '../../../utils/in-flight.js';
import {
    createPhotoLandedEvent,
    createPhotoPickedEvent,
    createPhotoRemovedEvent,
    createPhotoUploadingEvent,
} from '../health-events.js';
import '../food-thumbnail/food-thumbnail.component.js';

const styles = cssStyleSheet(stylesText);

const DEFAULT_ADD_LABEL = '+ Add photo';

const template = document.createElement('template');
template.innerHTML = `
    <div class="photo">
        <food-thumb id="image-thumb" alt=""></food-thumb>
        <div class="side">
            <div class="image-actions" id="image-actions" hidden>
                <button class="btn-image-add" id="btn-image-add" part="button" type="button">${DEFAULT_ADD_LABEL}</button>
                <button class="btn-image-replace" id="btn-image-replace" part="button" type="button" hidden>Replace</button>
                <button class="btn-image-remove" id="btn-image-remove" part="button" type="button" hidden>Remove</button>
            </div>
            <p class="image-error" id="image-error" hidden></p>
        </div>
        <input type="file" id="image-input" accept="image/jpeg,image/png,image/webp" hidden>
    </div>
`;

/** The row whose picture is shown. */
export interface PhotoTarget {
    /** The row's id, which an offline upload is queued against; null when the row is not saved yet. */
    localRef: string | null;
    /** The row's own picture. */
    path: string | null;
    /** A picture from elsewhere, shown read-only when the row has none (an OFF product's). */
    remote?: string | null;
    alt: string;
    editable: boolean;
}

/**
 * Story 403 — add / Replace / Remove for the picture on a food or a meal: one element where three
 * components each carried a copy (DLR #292).
 *
 * It uploads, queues and shows, and never writes a row. A pick it has uploaded is offered to the
 * host as `PHOTO_PICKED`, and Remove as `PHOTO_REMOVED`; the host saves or holds the path and
 * answers through `respondWith`, so a failed save shows here. With a `localRef` an offline pick is
 * queued against the row, and the drain puts it there (story 362); without one the row does not
 * exist yet, so there is nothing for a queued photo to land on and the upload is all or nothing
 * (story 355).
 *
 * Attributes: `scope` (`food` | `meal`) and `add-label`. The buttons are `::part(button)`, for a host
 * whose background their outline would vanish on.
 */
export class PhotoControls extends HTMLElement {
    static get observedAttributes() { return ['add-label']; }

    private target: PhotoTarget = { localRef: null, path: null, alt: '', editable: false };
    /** A queued upload's id — shown as the spinner, never written to the row. */
    private pendingQueueId: string | null = null;
    private uploading = false;
    /** Bumped whenever the upload in flight is let go of, so its late result is dropped. */
    private generation = 0;
    private broadcastChannel: BroadcastChannel | null = null;
    private readonly log = createComponentLogger('photo-controls');

    constructor() {
        super();
        const shadow = this.attachShadow({ mode: 'open' });
        shadow.adoptedStyleSheets = [styles];
        shadow.appendChild(template.content.cloneNode(true));

        const input = shadow.getElementById('image-input') as HTMLInputElement;
        shadow.getElementById('btn-image-add')!.addEventListener('click', () => input.click());
        shadow.getElementById('btn-image-replace')!.addEventListener('click', () => input.click());
        shadow.getElementById('btn-image-remove')!.addEventListener('click', () => void this.handleRemove());
        input.addEventListener('change', () => {
            const file = input.files?.[0];
            if (file) void this.handlePicked(file);
            input.value = '';
        });
    }

    attributeChangedCallback(name: string, _oldValue: string | null, newValue: string | null): void {
        if (name === 'add-label') {
            this.shadowRoot!.getElementById('btn-image-add')!.textContent = newValue ?? DEFAULT_ADD_LABEL;
        }
    }

    connectedCallback(): void {
        if (typeof BroadcastChannel !== 'undefined') {
            this.broadcastChannel = new BroadcastChannel(IMAGE_UPLOAD_SUCCESS_CHANNEL);
            this.broadcastChannel.onmessage = (e: MessageEvent<ImageUploadSuccessMessage>) => this.adopt(e.data);
        }
        this.render();
    }

    disconnectedCallback(): void {
        this.broadcastChannel?.close();
        this.broadcastChannel = null;
    }

    /** Another row: an upload in flight for the last one is let go of. A queued one still lands on its own row. */
    show(target: PhotoTarget): void {
        this.target = { ...target };
        this.pendingQueueId = null;
        this.letGo();
        this.clearError();
        this.render();
    }

    /** The same row, edited or only looked at (add-ingredient mode). */
    set editable(value: boolean) {
        this.target = { ...this.target, editable: value };
        this.render();
    }

    private get scope(): ImageScope {
        const scope = this.getAttribute('scope');
        if (scope !== 'food' && scope !== 'meal') throw new Error(`<photo-controls> needs scope="food" or scope="meal", got ${scope}`);
        return scope;
    }

    private async handlePicked(file: File): Promise<void> {
        this.clearError();
        this.letGo();
        const generation = this.generation;
        const filename = file.name || 'photo.jpg';
        this.uploading = true;
        this.dispatchEvent(createPhotoUploadingEvent({ uploading: true }));
        this.render();
        try {
            const { localRef } = this.target;
            const result = localRef
                ? await FilesService.uploadImageOrQueue(this.scope, file, filename, { local_ref: localRef })
                : { status: 'uploaded' as const, ...await FilesService.uploadImage(this.scope, file, filename) };
            if (generation !== this.generation) {
                this.log.debug('upload settled after it was let go of — dropped', { status: result.status });
                return;
            }
            this.endUpload();
            // A photo still queued for this row would ship after this one and land over it.
            const replaced = this.pendingQueueId;
            if (result.status === 'queued') {
                this.pendingQueueId = result.queue_id;
                this.showError('Photo will upload when online');
            } else {
                await dispatchAndSettle(this, createPhotoPickedEvent({ image_path: result.image_path }));
                if (generation !== this.generation) return;
                this.target = { ...this.target, path: result.image_path };
                this.pendingQueueId = null;
            }
            if (replaced) await cancelQueuedUpload(replaced, this.log);
        } catch (err) {
            if (generation !== this.generation) {
                this.log.debug('upload failed after it was let go of — dropped', err);
                return;
            }
            this.endUpload();
            this.log.error('photo upload or save failed', err);
            this.showError(err instanceof Error ? err.message : String(err));
        }
        this.render();
    }

    private async handleRemove(): Promise<void> {
        this.clearError();
        // Mid-upload this abandons the upload, and a host holding a save gets it back at once.
        this.letGo();
        this.render();
        try {
            await dispatchAndSettle(this, createPhotoRemovedEvent());
        } catch (err) {
            this.log.error('photo remove failed', err);
            this.showError(err instanceof Error ? err.message : String(err));
            return;
        }
        // Story 370 (pwa-nutrition-15): a photo still waiting to ship would be put back on the row.
        if (this.pendingQueueId) await cancelQueuedUpload(this.pendingQueueId, this.log);
        this.pendingQueueId = null;
        this.target = { ...this.target, path: null };
        this.render();
    }

    /** A queued upload shipped; the drain already put it on its row (story 362). */
    private adopt(data: ImageUploadSuccessMessage | null): void {
        if (!data || data.type !== 'image-upload-success' || !data.image_path) return;
        const { localRef } = this.target;
        const matches = (localRef && data.local_ref === localRef)
            || (this.pendingQueueId && data.queue_id === this.pendingQueueId);
        if (!matches) return;
        this.pendingQueueId = null;
        this.target = { ...this.target, path: data.image_path };
        this.clearError();
        this.render();
        this.dispatchEvent(createPhotoLandedEvent({ image_path: data.image_path }));
    }

    private letGo(): void {
        this.generation++;
        this.endUpload();
    }

    private endUpload(): void {
        if (!this.uploading) return;
        this.uploading = false;
        this.dispatchEvent(createPhotoUploadingEvent({ uploading: false }));
    }

    private render(): void {
        const shadow = this.shadowRoot!;
        const thumb = shadow.getElementById('image-thumb')!;
        // `pending:` is food-thumb's spinner. It never leaves this element.
        const path = this.uploading
            ? 'pending:upload'
            : this.target.path ?? (this.pendingQueueId ? `pending:${this.pendingQueueId}` : null);
        thumb.removeAttribute('path');
        thumb.removeAttribute('remote');
        if (path) thumb.setAttribute('path', path);
        else if (this.target.remote) thumb.setAttribute('remote', this.target.remote);
        thumb.setAttribute('alt', this.target.alt);

        shadow.getElementById('image-actions')!.hidden = !this.target.editable;
        shadow.getElementById('btn-image-add')!.hidden = !!path;
        shadow.getElementById('btn-image-replace')!.hidden = !path;
        shadow.getElementById('btn-image-remove')!.hidden = !path;
    }

    private showError(message: string): void {
        const error = this.shadowRoot!.getElementById('image-error')!;
        error.textContent = message;
        error.hidden = false;
    }

    private clearError(): void {
        const error = this.shadowRoot!.getElementById('image-error')!;
        error.textContent = '';
        error.hidden = true;
    }
}

if (!customElements.get('photo-controls')) {
    customElements.define('photo-controls', PhotoControls);
}
