import { inStoreItemCode } from '@motivation/shared';

/**
 * Story 342 — what a pending barcode binding actually promises, in the user's terms.
 *
 * The two cases are genuinely different and the old one-line prompt said neither. An
 * in-store code binds through its `item_code` (spike 336), so the pick answers *every*
 * package of that product from that shop — that is the whole reason the feature exists
 * for weighed produce. A regular GS1 code binds only itself.
 *
 * Saying which one is in play is not decoration: on 2026-09-14 a 12-digit misread was
 * bound instead of the 13-digit sticker code, and because nothing on screen named the
 * code or its scope, it read as a success. Both components that can bind a code use
 * this, so they cannot drift apart.
 */
export interface BarcodeBinding {
    /** The stable per-product segment, or null when this is not an in-store code. */
    itemCode: string | null;
    /** One sentence naming what the binding will cover. */
    scope: string;
}

export function describeBarcodeBinding(barcode: string): BarcodeBinding {
    const itemCode = inStoreItemCode(barcode);
    return {
        itemCode,
        scope: itemCode
            ? `In-store code, item ${itemCode} — every package of this product from this shop will resolve here, whatever it weighs.`
            : 'Only this exact code will resolve here.',
    };
}

/** The confirmation shown once a code has been bound to a food. */
export function describeBarcodeBound(barcode: string, foodName: string): string {
    const { itemCode } = describeBarcodeBinding(barcode);
    return itemCode
        ? `${barcode} → ${foodName}. Every package with item code ${itemCode} resolves here now.`
        : `${barcode} → ${foodName}. That exact code resolves here now.`;
}
